using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestDbContextHelper
    {
        public static SchoolContext CreateContext(string? dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;
            return new SchoolContext(options);
        }

        public static SchoolContext CreateSeededContext(string? dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var context = CreateContext(dbName);
            SeedData(context);
            return context;
        }

        public static void SeedData(SchoolContext context)
        {
            var instructor1 = new Instructor
            {
                FirstMidName = "Kim",
                LastName = "Abercrombie",
                HireDate = DateTime.Parse("1995-03-11")
            };
            var instructor2 = new Instructor
            {
                FirstMidName = "Fadi",
                LastName = "Fakhouri",
                HireDate = DateTime.Parse("2002-07-06")
            };
            context.Instructors.AddRange(instructor1, instructor2);
            context.SaveChanges();

            var department1 = new Department
            {
                Name = "English",
                Budget = 350000,
                StartDate = DateTime.Parse("2007-09-01"),
                InstructorID = instructor1.ID
            };
            var department2 = new Department
            {
                Name = "Mathematics",
                Budget = 100000,
                StartDate = DateTime.Parse("2007-09-01"),
                InstructorID = instructor2.ID
            };
            context.Departments.AddRange(department1, department2);
            context.SaveChanges();

            var course1 = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = department1.DepartmentID
            };
            var course2 = new Course
            {
                CourseID = 4022,
                Title = "Microeconomics",
                Credits = 3,
                DepartmentID = department2.DepartmentID
            };
            context.Courses.AddRange(course1, course2);
            context.SaveChanges();

            var student1 = new Student
            {
                FirstMidName = "Carson",
                LastName = "Alexander",
                EnrollmentDate = DateTime.Parse("2010-09-01")
            };
            var student2 = new Student
            {
                FirstMidName = "Meredith",
                LastName = "Alonso",
                EnrollmentDate = DateTime.Parse("2012-09-01")
            };
            var student3 = new Student
            {
                FirstMidName = "Arturo",
                LastName = "Anand",
                EnrollmentDate = DateTime.Parse("2013-09-01")
            };
            context.Students.AddRange(student1, student2, student3);
            context.SaveChanges();

            context.Enrollments.Add(new Enrollment
            {
                StudentID = student1.ID,
                CourseID = course1.CourseID,
                Grade = Grade.A
            });
            context.SaveChanges();

            context.CourseAssignments.Add(new CourseAssignment
            {
                CourseID = course1.CourseID,
                InstructorID = instructor1.ID
            });
            context.SaveChanges();

            context.OfficeAssignments.Add(new OfficeAssignment
            {
                InstructorID = instructor2.ID,
                Location = "Smith 17"
            });
            context.SaveChanges();
        }
    }
}

using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Constructor_ValidInputs_SetsPageIndexAndTotalPages()
        {
            // Arrange
            var items = new List<string> { "a", "b", "c" };

            // Act
            var list = new PaginatedList<string>(items, 10, 2, 3);

            // Assert
            Assert.Equal(2, list.PageIndex);
            Assert.Equal(4, list.TotalPages); // ceil(10/3) = 4
            Assert.Equal(3, list.Count);
            Assert.Equal("a", list[0]);
            Assert.Equal("b", list[1]);
            Assert.Equal("c", list[2]);
        }

        [Theory]
        [InlineData(10, 3, 4)]   // ceil(10/3) = 4
        [InlineData(10, 5, 2)]   // ceil(10/5) = 2
        [InlineData(10, 10, 1)]  // ceil(10/10) = 1
        [InlineData(0, 5, 0)]    // ceil(0/5) = 0
        [InlineData(1, 5, 1)]    // ceil(1/5) = 1
        [InlineData(11, 5, 3)]   // ceil(11/5) = 3
        public void Constructor_VariousCounts_CalculatesTotalPagesCorrectly(int totalCount, int pageSize, int expectedTotalPages)
        {
            // Arrange
            var items = new List<int>();

            // Act
            var list = new PaginatedList<int>(items, totalCount, 1, pageSize);

            // Assert
            Assert.Equal(expectedTotalPages, list.TotalPages);
        }

        [Theory]
        [InlineData(1, false)]   // First page: no previous
        [InlineData(2, true)]    // Second page: has previous
        [InlineData(3, true)]    // Third page: has previous
        public void HasPreviousPage_VariousPageIndexes_ReturnsExpected(int pageIndex, bool expected)
        {
            // Arrange & Act
            var list = new PaginatedList<int>(new List<int>(), 30, pageIndex, 10);

            // Assert
            Assert.Equal(expected, list.HasPreviousPage);
        }

        [Theory]
        [InlineData(1, 3, true)]   // Page 1 of 3: has next
        [InlineData(2, 3, true)]   // Page 2 of 3: has next
        [InlineData(3, 3, false)]  // Page 3 of 3: no next
        [InlineData(1, 1, false)]  // Page 1 of 1: no next
        public void HasNextPage_VariousPageIndexes_ReturnsExpected(int pageIndex, int totalPages, bool expected)
        {
            // Arrange
            int pageSize = 10;
            int totalCount = totalPages * pageSize;

            // Act
            var list = new PaginatedList<int>(new List<int>(), totalCount, pageIndex, pageSize);

            // Assert
            Assert.Equal(expected, list.HasNextPage);
        }

        [Fact]
        public void Create_FromQueryable_ReturnsCorrectPage()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var page1 = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.Equal(1, page1.PageIndex);
            Assert.Equal(3, page1.TotalPages);
            Assert.Equal(10, page1.Count);
            Assert.Equal(1, page1[0]);
            Assert.Equal(10, page1[9]);
            Assert.True(page1.HasNextPage);
            Assert.False(page1.HasPreviousPage);
        }

        [Fact]
        public void Create_SecondPage_ReturnsCorrectItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var page2 = PaginatedList<int>.Create(source, 2, 10);

            // Assert
            Assert.Equal(2, page2.PageIndex);
            Assert.Equal(10, page2.Count);
            Assert.Equal(11, page2[0]);
            Assert.Equal(20, page2[9]);
            Assert.True(page2.HasPreviousPage);
            Assert.True(page2.HasNextPage);
        }

        [Fact]
        public void Create_LastPage_ReturnsRemainingItems()
        {
            // Arrange
            var source = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var page3 = PaginatedList<int>.Create(source, 3, 10);

            // Assert
            Assert.Equal(3, page3.PageIndex);
            Assert.Equal(5, page3.Count);
            Assert.Equal(21, page3[0]);
            Assert.Equal(25, page3[4]);
            Assert.True(page3.HasPreviousPage);
            Assert.False(page3.HasNextPage);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            // Arrange
            var source = Enumerable.Empty<int>().AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Create_SingleItem_ReturnsOnePageOneItem()
        {
            // Arrange
            var source = new[] { 42 }.AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.Single(result);
            Assert.Equal(42, result[0]);
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasPreviousPage);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void Create_ExactlyOneFullPage_NoNextPage()
        {
            // Arrange
            var source = Enumerable.Range(1, 10).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(source, 1, 10);

            // Assert
            Assert.Equal(10, result.Count);
            Assert.Equal(1, result.TotalPages);
            Assert.False(result.HasNextPage);
            Assert.False(result.HasPreviousPage);
        }
    }
}

using System;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut;

        public NotificationServiceTests()
        {
            _sut = new NotificationService();
            // Drain the static queue to avoid cross-test contamination
            while (_sut.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _sut.Dispose();
        }

        [Fact]
        public void SendNotification_WithDisplayName_CreatesNotificationWithCorrectMessage()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Contains("John Doe", notification.Message);
            Assert.Contains("created", notification.Message);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesIdInMessage()
        {
            // Arrange & Act
            _sut.SendNotification("Course", "42", EntityOperation.UPDATE, "Teacher");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("ID: 42", notification.Message);
            Assert.Contains("updated", notification.Message);
            Assert.Equal("Teacher", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_DeleteOperation_GeneratesDeleteMessage()
        {
            // Arrange & Act
            _sut.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("deleted", notification.Message);
            Assert.Contains("Engineering", notification.Message);
            Assert.Equal("System", notification.CreatedBy); // Default user
        }

        [Fact]
        public void SendNotification_NullUserName_DefaultsToSystem()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "1", EntityOperation.CREATE, null);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToCurrentTime()
        {
            // Arrange
            var before = DateTime.Now;

            // Act
            _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.InRange(notification.CreatedAt, before, DateTime.Now.AddSeconds(1));
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            // Act
            var result = _sut.ReceiveNotification();

            // Assert
            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_MultipleMessages_ReturnsFIFO()
        {
            // Arrange
            _sut.SendNotification("Student", "1", "First", EntityOperation.CREATE);
            _sut.SendNotification("Course", "2", "Second", EntityOperation.UPDATE);
            _sut.SendNotification("Department", "3", "Third", EntityOperation.DELETE);

            // Act & Assert
            var first = _sut.ReceiveNotification();
            Assert.NotNull(first);
            Assert.Equal("Student", first.EntityType);
            Assert.Contains("First", first.Message);

            var second = _sut.ReceiveNotification();
            Assert.NotNull(second);
            Assert.Equal("Course", second.EntityType);
            Assert.Contains("Second", second.Message);

            var third = _sut.ReceiveNotification();
            Assert.NotNull(third);
            Assert.Equal("Department", third.EntityType);
            Assert.Contains("Third", third.Message);

            // Queue should be empty now
            Assert.Null(_sut.ReceiveNotification());
        }

        [Fact]
        public void SendNotification_CreateOperation_MessageSaysCreated()
        {
            // Act
            _sut.SendNotification("Student", "1", "Alice Smith", EntityOperation.CREATE);
            var notification = _sut.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Equal("New Student 'Alice Smith' has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_UpdateOperation_MessageSaysUpdated()
        {
            // Act
            _sut.SendNotification("Course", "100", "Math 101", EntityOperation.UPDATE);
            var notification = _sut.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Equal("Course 'Math 101' has been updated", notification.Message);
        }

        [Fact]
        public void SendNotification_DeleteOperation_MessageSaysDeleted()
        {
            // Act
            _sut.SendNotification("Department", "5", "Physics", EntityOperation.DELETE);
            var notification = _sut.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Equal("Department 'Physics' has been deleted", notification.Message);
        }

        [Fact]
        public void SendNotification_NoDisplayName_UsesEntityIdInMessage()
        {
            // Act
            _sut.SendNotification("Student", "99", null, EntityOperation.CREATE);
            var notification = _sut.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Equal("New Student (ID: 99) has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_EmptyDisplayName_UsesEntityIdInMessage()
        {
            // Act
            _sut.SendNotification("Student", "99", "  ", EntityOperation.CREATE);
            var notification = _sut.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Equal("New Student (ID: 99) has been created", notification.Message);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // Act & Assert (no-op implementation, just ensure no exception)
            var exception = Record.Exception(() => _sut.MarkAsRead(1));
            Assert.Null(exception);
        }

        [Fact]
        public void MarkAsRead_NonExistentId_DoesNotThrow()
        {
            // Act & Assert
            var exception = Record.Exception(() => _sut.MarkAsRead(-999));
            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_CanBeCalledMultipleTimes()
        {
            // Act & Assert
            var service = new NotificationService();
            var exception = Record.Exception(() =>
            {
                service.Dispose();
                service.Dispose();
            });
            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_OverloadWithoutDisplayName_DelegatesToFullMethod()
        {
            // Act
            _sut.SendNotification("Instructor", "7", EntityOperation.UPDATE);
            var notification = _sut.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Equal("Instructor", notification.EntityType);
            Assert.Equal("7", notification.EntityId);
            Assert.Equal("UPDATE", notification.Operation);
            Assert.Contains("ID: 7", notification.Message);
        }

        [Fact]
        public void SendNotification_SetsIsReadToFalse()
        {
            // Act
            _sut.SendNotification("Student", "1", "Test", EntityOperation.CREATE);
            var notification = _sut.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.False(notification.IsRead);
        }
    }
}

