using System;
using System.Linq;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class SchoolContextTests
    {
        [Fact]
        public void SchoolContext_CanCreateAndQueryStudents()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "User",
                EnrollmentDate = new DateTime(2023, 1, 1)
            };

            // Act
            context.Students.Add(student);
            context.SaveChanges();

            // Assert
            var retrieved = context.Students.First(s => s.LastName == "User");
            Assert.Equal("Test", retrieved.FirstMidName);
            Assert.Equal(new DateTime(2023, 1, 1), retrieved.EnrollmentDate);
        }

        [Fact]
        public void SchoolContext_CanCreateAndQueryInstructors()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();
            var instructor = new Instructor
            {
                FirstMidName = "Jane",
                LastName = "Doe",
                HireDate = new DateTime(2000, 6, 15)
            };

            // Act
            context.Instructors.Add(instructor);
            context.SaveChanges();

            // Assert
            var retrieved = context.Instructors.First(i => i.LastName == "Doe");
            Assert.Equal("Jane", retrieved.FirstMidName);
            Assert.Equal(new DateTime(2000, 6, 15), retrieved.HireDate);
        }

        [Fact]
        public void SchoolContext_CourseAssignment_HasCompositeKey()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();
            var instructor = new Instructor { FirstMidName = "A", LastName = "B", HireDate = DateTime.Now };
            context.Instructors.Add(instructor);
            context.SaveChanges();

            var dept = new Department { Name = "Test", Budget = 1000, StartDate = DateTime.Now };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course { CourseID = 9999, Title = "Test Course", Credits = 3, DepartmentID = dept.DepartmentID };
            context.Courses.Add(course);
            context.SaveChanges();

            // Act
            var ca = new CourseAssignment { CourseID = course.CourseID, InstructorID = instructor.ID };
            context.CourseAssignments.Add(ca);
            context.SaveChanges();

            // Assert
            var retrieved = context.CourseAssignments.Find(course.CourseID, instructor.ID);
            Assert.NotNull(retrieved);
            Assert.Equal(course.CourseID, retrieved!.CourseID);
            Assert.Equal(instructor.ID, retrieved.InstructorID);
        }

        [Fact]
        public void SchoolContext_CanCreateDepartmentWithNullInstructor()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();
            var dept = new Department
            {
                Name = "Orphan Dept",
                Budget = 50000,
                StartDate = new DateTime(2023, 1, 1),
                InstructorID = null
            };

            // Act
            context.Departments.Add(dept);
            context.SaveChanges();

            // Assert
            var retrieved = context.Departments.First(d => d.Name == "Orphan Dept");
            Assert.Null(retrieved.InstructorID);
            Assert.Equal(50000m, retrieved.Budget);
        }

        [Fact]
        public void SchoolContext_CanCreateEnrollmentWithNullGrade()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();
            var student = new Student { FirstMidName = "A", LastName = "B", EnrollmentDate = DateTime.Now };
            context.Students.Add(student);
            var dept = new Department { Name = "D", Budget = 1000, StartDate = DateTime.Now };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course { CourseID = 8888, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            context.Courses.Add(course);
            context.SaveChanges();

            // Act
            var enrollment = new Enrollment { StudentID = student.ID, CourseID = course.CourseID, Grade = null };
            context.Enrollments.Add(enrollment);
            context.SaveChanges();

            // Assert
            var retrieved = context.Enrollments.First(e => e.StudentID == student.ID);
            Assert.Null(retrieved.Grade);
            Assert.Equal(student.ID, retrieved.StudentID);
            Assert.Equal(course.CourseID, retrieved.CourseID);
        }

        [Fact]
        public void SchoolContext_OfficeAssignment_UsesInstructorIDAsKey()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();
            var instructor = new Instructor { FirstMidName = "A", LastName = "B", HireDate = DateTime.Now };
            context.Instructors.Add(instructor);
            context.SaveChanges();

            // Act
            var oa = new OfficeAssignment { InstructorID = instructor.ID, Location = "Room 202" };
            context.OfficeAssignments.Add(oa);
            context.SaveChanges();

            // Assert
            var retrieved = context.OfficeAssignments.Find(instructor.ID);
            Assert.NotNull(retrieved);
            Assert.Equal("Room 202", retrieved!.Location);
        }

        [Fact]
        public void SchoolContext_AllDbSetsAreAvailable()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();

            // Assert
            Assert.NotNull(context.Courses);
            Assert.NotNull(context.Enrollments);
            Assert.NotNull(context.Departments);
            Assert.NotNull(context.OfficeAssignments);
            Assert.NotNull(context.CourseAssignments);
            Assert.NotNull(context.People);
            Assert.NotNull(context.Students);
            Assert.NotNull(context.Instructors);
            Assert.NotNull(context.Notifications);
        }

        [Fact]
        public void SchoolContext_StudentAndInstructor_SharePeopleDbSet()
        {
            // Arrange
            using var context = TestDbContextHelper.CreateContext();
            context.Students.Add(new Student { FirstMidName = "S", LastName = "Student", EnrollmentDate = DateTime.Now });
            context.Instructors.Add(new Instructor { FirstMidName = "I", LastName = "Instructor", HireDate = DateTime.Now });
            context.SaveChanges();

            // Assert - Both appear in People
            Assert.True(context.People.Count() >= 2);
            Assert.Contains(context.People, p => p.LastName == "Student");
            Assert.Contains(context.People, p => p.LastName == "Instructor");
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Controllers;
