using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class DepartmentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly DepartmentsController _controller;

        public DepartmentsControllerTests()
        {
            _context = TestDbContextHelper.CreateSeededContext();
            _controller = new DepartmentsController(_context);
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
            _controller.TempData = new TempDataDictionary(
                _controller.ControllerContext.HttpContext,
                new SessionStateTempDataProvider());
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        // --- Index ---

        [Fact]
        public void Index_ReturnsViewWithDepartments()
        {
            // Act
            var result = _controller.Index() as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result!.Model as List<Department>;
            Assert.NotNull(model);
            Assert.True(model!.Count > 0);
        }

        [Fact]
        public void Index_ReturnsDepartmentsFromSeededData()
        {
            // Act
            var result = _controller.Index() as ViewResult;
            var model = result!.Model as List<Department>;

            // Assert
            Assert.NotNull(model);
            Assert.Equal(2, model!.Count); // We seeded 2 departments
            Assert.Contains(model, d => d.Name == "English");
            Assert.Contains(model, d => d.Name == "Mathematics");
        }

        // --- Details ---

        [Fact]
        public void Details_ValidId_ReturnsViewWithDepartment()
        {
            // Arrange
            var dept = _context.Departments.First();

            // Act
            var result = _controller.Details(dept.DepartmentID) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result!.Model as Department;
            Assert.NotNull(model);
            Assert.Equal(dept.DepartmentID, model!.DepartmentID);
            Assert.Equal(dept.Name, model.Name);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Details(null) as StatusCodeResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal(400, result!.StatusCode);
        }

        [Fact]
        public void Details_InvalidId_ReturnsNotFound()
        {
            // Act
            var result = _controller.Details(99999) as NotFoundResult;

            // Assert
            Assert.NotNull(result);
        }

        // --- Create GET ---

        [Fact]
        public void Create_Get_ReturnsView()
        {
            // Act
            var result = _controller.Create() as ViewResult;

            // Assert
            Assert.NotNull(result);
        }

        // --- Create POST ---

        [Fact]
        public void Create_Post_ValidDepartment_AddsAndRedirects()
        {
            // Arrange
            var dept = new Department
            {
                Name = "Physics",
                Budget = 200000,
                StartDate = new DateTime(2023, 1, 1)
            };
            var countBefore = _context.Departments.Count();

            // Act
            var result = _controller.Create(dept) as RedirectToActionResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Index", result!.ActionName);
            Assert.Equal(countBefore + 1, _context.Departments.Count());
            var created = _context.Departments.First(d => d.Name == "Physics");
            Assert.Equal(200000m, created.Budget);
        }

        [Fact]
        public void Create_Post_InvalidModel_ReturnsView()
        {
            // Arrange
            _controller.ModelState.AddModelError("Name", "Required");
            var dept = new Department { Name = "Test", Budget = 1000, StartDate = DateTime.Now };

            // Act
            var result = _controller.Create(dept) as ViewResult;

            // Assert
            Assert.NotNull(result);
        }

        // --- Edit GET ---

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithDepartment()
        {
            // Arrange
            var dept = _context.Departments.First();

            // Act
            var result = _controller.Edit(dept.DepartmentID) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result!.Model as Department;
            Assert.NotNull(model);
            Assert.Equal(dept.DepartmentID, model!.DepartmentID);
        }

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Edit(null) as StatusCodeResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal(400, result!.StatusCode);
        }

        [Fact]
        public void Edit_Get_InvalidId_ReturnsNotFound()
        {
            // Act
            var result = _controller.Edit(99999) as NotFoundResult;

            // Assert
            Assert.NotNull(result);
        }

        // --- Edit POST ---

        [Fact]
        public void Edit_Post_ValidDepartment_UpdatesAndRedirects()
        {
            // Arrange
            var dept = _context.Departments.First();
            var editedDept = new Department
            {
                DepartmentID = dept.DepartmentID,
                Name = "Updated Name",
                Budget = 999999,
                StartDate = dept.StartDate,
                InstructorID = dept.InstructorID
            };
            _context.Entry(dept).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            // Act
            var result = _controller.Edit(editedDept) as RedirectToActionResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Index", result!.ActionName);
        }

        [Fact]
        public void Edit_Post_InvalidModel_ReturnsView()
        {
            // Arrange
            _controller.ModelState.AddModelError("Name", "Required");
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Test",
                Budget = 1000,
                StartDate = DateTime.Now
            };

            // Act
            var result = _controller.Edit(dept) as ViewResult;

            // Assert
            Assert.NotNull(result);
        }

        // --- Delete GET ---

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithDepartment()
        {
            // Arrange
            var dept = _context.Departments.First();

            // Act
            var result = _controller.Delete(dept.DepartmentID) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result!.Model as Department;
            Assert.NotNull(model);
            Assert.Equal(dept.DepartmentID, model!.DepartmentID);
        }

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Delete(null) as StatusCodeResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal(400, result!.StatusCode);
        }

        [Fact]
        public void Delete_Get_InvalidId_ReturnsNotFound()
        {
            // Act
            var result = _controller.Delete(99999) as NotFoundResult;

            // Assert
            Assert.NotNull(result);
        }

        // --- DeleteConfirmed POST ---

        [Fact]
        public void DeleteConfirmed_ValidId_RemovesDepartmentAndRedirects()
        {
            // Arrange
            var dept = _context.Departments.First();
            var countBefore = _context.Departments.Count();

            // Act
            var result = _controller.DeleteConfirmed(dept.DepartmentID) as RedirectToActionResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Index", result!.ActionName);
            Assert.Equal(countBefore - 1, _context.Departments.Count());
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class CoursesControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _mockEnv;
        private readonly Mock<ILogger<CoursesController>> _mockLogger;
        private readonly string _tempDir;

        public CoursesControllerTests()
        {
            _context = TestDbContextHelper.CreateSeededContext();
            _mockEnv = new Mock<IWebHostEnvironment>();
            _mockLogger = new Mock<ILogger<CoursesController>>();

            _tempDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
            Directory.CreateDirectory(_tempDir);
            _mockEnv.Setup(e => e.WebRootPath).Returns(_tempDir);
            _mockEnv.Setup(e => e.ContentRootPath).Returns(_tempDir);

            _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
            _controller.TempData = new TempDataDictionary(
                _controller.ControllerContext.HttpContext,
                new SessionStateTempDataProvider());
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
            try { Directory.Delete(_tempDir, true); } catch { }
        }

        // --- Index ---

        [Fact]
        public void Index_ReturnsViewWithCourses()
        {
            // Act
            var result = _controller.Index() as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result!.Model as List<Course>;
            Assert.NotNull(model);
            Assert.True(model!.Count > 0);
        }

        [Fact]
        public void Index_CoursesIncludeDepartment()
        {
            // Act
            var result = _controller.Index() as ViewResult;
            var model = result!.Model as List<Course>;

            // Assert - InMemory doesn't do Include, but Department is set via FK
            Assert.NotNull(model);
            Assert.Equal(2, model!.Count); // We seeded 2 courses
        }

        // --- Details ---

        [Fact]
        public void Details_ValidId_ReturnsViewWithCourse()
        {
            // Arrange
            var course = _context.Courses.First();

            // Act
            var result = _controller.Details(course.CourseID) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result!.Model as Course;
            Assert.NotNull(model);
            Assert.Equal(course.CourseID, model!.CourseID);
            Assert.Equal(course.Title, model.Title);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Details(null) as StatusCodeResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal(400, result!.StatusCode);
        }

        // --- Create GET ---

        [Fact]
        public void Create_Get_ReturnsViewWithNewCourse()
        {
            // Act
            var result = _controller.Create() as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result!.Model as Course;
            Assert.NotNull(model);
        }

        // --- Create POST ---

        [Fact]
        public void Create_Post_ValidCourse_AddsAndRedirects()
        {
            // Arrange
            var course = new Course
            {
                CourseID = 9999,
                Title = "New Course",
                Credits = 4,
                DepartmentID = _context.Departments.First().DepartmentID
            };
            var countBefore = _context.Courses.Count();

            // Act
            var result = _controller.Create(course, null) as RedirectToActionResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Index", result!.ActionName);
            Assert.Equal(countBefore + 1, _context.Courses.Count());
            var created = _context.Courses.Find(9999);
            Assert.NotNull(created);
            Assert.Equal("New Course", created!.Title);
            Assert.Equal(4, created.Credits);
        }

        [Fact]
        public void Create_Post_InvalidModel_ReturnsView()
        {
            // Arrange
            _controller.ModelState.AddModelError("Title", "Required");
            var course = new Course { CourseID = 7777, Title = "Test", Credits = 3 };

            // Act
            var result = _controller.Create(course, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
        }

        [Fact]
        public void Create_Post_WithInvalidImageExtension_ReturnsViewWithError()
        {
            // Arrange
            var course = new Course
            {
                CourseID = 8888,
                Title = "With Bad Image",
                Credits = 3,
                DepartmentID = _context.Departments.First().DepartmentID
            };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.exe");
            mockFile.Setup(f => f.Length).Returns(1024);

            // Act
            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_Post_WithOversizedImage_ReturnsViewWithError()
        {
            // Arrange
            var course = new Course
            {
                CourseID = 8889,
                Title = "With Big Image",
                Credits = 3,
                DepartmentID = _context.Departments.First().DepartmentID
            };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.jpg");
            mockFile.Setup(f => f.Length).Returns(6 * 1024 * 1024); // 6MB > 5MB limit

            // Act
            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_Post_WithValidImage_SavesFileAndRedirects()
        {
            // Arrange
            var course = new Course
            {
                CourseID = 7778,
                Title = "With Image",
                Credits = 3,
                DepartmentID = _context.Departments.First().DepartmentID
            };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.jpg");
            mockFile.Setup(f => f.Length).Returns(1024);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            // Act
            var result = _controller.Create(course, mockFile.Object) as RedirectToActionResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Index", result!.ActionName);
            var saved = _context.Courses.Find(7778);
            Assert.NotNull(saved);
            Assert.NotNull(saved!.TeachingMaterialImagePath);
            Assert.StartsWith("/Uploads/TeachingMaterials/", saved.TeachingMaterialImagePath);
        }

        // --- Edit GET ---

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithCourse()
        {
            // Arrange
            var course = _context.Courses.First();

            // Act
            var result = _controller.Edit(course.CourseID) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result!.Model as Course;
            Assert.NotNull(model);
            Assert.Equal(course.CourseID, model!.CourseID);
        }

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Edit(null) as StatusCodeResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal(400, result!.StatusCode);
        }

        [Fact]
        public void Edit_Get_InvalidId_ReturnsNotFound()
        {
            // Act
            var result = _controller.Edit(99999) as NotFoundResult;

            // Assert
            Assert.NotNull(result);
        }

        // --- Edit POST ---

        [Fact]
        public void Edit_Post_ValidCourse_UpdatesAndRedirects()
        {
            // Arrange
            var course = _context.Courses.First();
            var editedCourse = new Course
            {
                CourseID = course.CourseID,
                Title = "Updated Title",
                Credits = 5,
                DepartmentID = course.DepartmentID
            };
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            // Act
            var result = _controller.Edit(editedCourse, null) as RedirectToActionResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Index", result!.ActionName);
        }

        [Fact]
        public void Edit_Post_InvalidModel_ReturnsView()
        {
            // Arrange
            _controller.ModelState.AddModelError("Title", "Required");
            var course = new Course { CourseID = 1050, Title = "Test", Credits = 3 };

            // Act
            var result = _controller.Edit(course, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
        }

        [Fact]
        public void Edit_Post_WithInvalidImageExtension_ReturnsViewWithError()
        {
            // Arrange
            var course = _context.Courses.First();
            var editCourse = new Course
            {
                CourseID = course.CourseID,
                Title = course.Title,
                Credits = course.Credits,
                DepartmentID = course.DepartmentID
            };
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.pdf");
            mockFile.Setup(f => f.Length).Returns(1024);

            // Act
            var result = _controller.Edit(editCourse, mockFile.Object) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_Post_WithOversizedImage_ReturnsViewWithError()
        {
            // Arrange
            var course = _context.Courses.First();
            var editCourse = new Course
            {
                CourseID = course.CourseID,
                Title = course.Title,
                Credits = course.Credits,
                DepartmentID = course.DepartmentID
            };
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("big.png");
            mockFile.Setup(f => f.Length).Returns(10 * 1024 * 1024); // 10MB

            // Act
            var result = _controller.Edit(editCourse, mockFile.Object) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        // --- Delete GET ---

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithCourse()
        {
            // Arrange
            var course = _context.Courses.First();

            // Act
            var result = _controller.Delete(course.CourseID) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result!.Model as Course;
            Assert.NotNull(model);
            Assert.Equal(course.CourseID, model!.CourseID);
        }

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Delete(null) as StatusCodeResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal(400, result!.StatusCode);
        }

        // --- DeleteConfirmed POST ---

        [Fact]
        public void DeleteConfirmed_ValidId_RemovesCourseAndRedirects()
        {
            // Arrange
            var course = _context.Courses.First();
            var countBefore = _context.Courses.Count();

            // Act
            var result = _controller.DeleteConfirmed(course.CourseID) as RedirectToActionResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Index", result!.ActionName);
            Assert.Equal(countBefore - 1, _context.Courses.Count());
        }

        [Fact]
        public void DeleteConfirmed_CourseWithImagePath_AttemptsFileDelete()
        {
            // Arrange - set up a course with an image path
            var course = _context.Courses.First();
            course.TeachingMaterialImagePath = "/Uploads/TeachingMaterials/test.jpg";
            _context.SaveChanges();

            // Act - should not throw even if file doesn't exist
            var result = _controller.DeleteConfirmed(course.CourseID) as RedirectToActionResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Index", result!.ActionName);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            _context = TestDbContextHelper.CreateSeededContext();
            _controller = new InstructorsController(_context);
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
            _controller.TempData = new TempDataDictionary(
                _controller.ControllerContext.HttpContext,
                new SessionStateTempDataProvider());
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        // --- Index ---

        [Fact]
        public void Index_NoParameters_ReturnsViewWithInstructorIndexData()
        {
            // Act
            var result = _controller.Index(null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result!.Model as InstructorIndexData;
            Assert.NotNull(model);
            Assert.NotNull(model!.Instructors);
            Assert.True(model.Instructors.Any());
        }

        [Fact]
        public void Index_WithInstructorId_PopulatesCourses()
        {
            // Arrange
            var instructor = _context.Instructors.First(i => i.CourseAssignments != null && i.CourseAssignments.Any());

            // Act
            var result = _controller.Index(instructor.ID, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result!.Model as InstructorIndexData;
            Assert.NotNull(model);
            Assert.NotNull(model!.Courses);
            Assert.True(model.Courses.Any());
        }

        // --- Details ---

        [Fact]
        public void Details_ValidId_ReturnsViewWithInstructor()
        {
            // Arrange
            var instructor = _context.Instructors.First();

            // Act
            var result = _controller.Details(instructor.ID) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result!.Model as Instructor;
            Assert.NotNull(model);
            Assert.Equal(instructor.ID, model!.ID);
            Assert.Equal(instructor.LastName, model.LastName);
            Assert.Equal(instructor.FirstMidName, model.FirstMidName);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Details(null) as StatusCodeResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal(400, result!.StatusCode);
        }

        [Fact]
        public void Details_InvalidId_ReturnsNotFound()
        {
            // Act
            var result = _controller.Details(99999) as NotFoundResult;

            // Assert
            Assert.NotNull(result);
        }

        // --- Create GET ---

        [Fact]
        public void Create_Get_ReturnsViewWithInstructor()
        {
            // Act
            var result = _controller.Create() as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result!.Model as Instructor;
            Assert.NotNull(model);
            Assert.NotNull(model!.CourseAssignments);
            Assert.Empty(model.CourseAssignments);
        }

        // --- Create POST ---

        [Fact]
        public void Create_Post_ValidInstructor_AddsAndRedirects()
        {
            // Arrange
            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "Instructor",
                HireDate = new DateTime(2023, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            };
            var countBefore = _context.Instructors.Count();

            // Act
            var result = _controller.Create(instructor, null) as RedirectToActionResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Index", result!.ActionName);
            Assert.Equal(countBefore + 1, _context.Instructors.Count());
            var created = _context.Instructors.First(i => i.LastName == "Instructor");
            Assert.Equal("New", created.FirstMidName);
            Assert.Equal(new DateTime(2023, 1, 1), created.HireDate);
        }

        [Fact]
        public void Create_Post_WithSelectedCourses_AddsCourseAssignments()
        {
            // Arrange
            var instructor = new Instructor
            {
                FirstMidName = "Course",
                LastName = "Teacher",
                HireDate = new DateTime(2023, 1, 1)
            };
            var courseId = _context.Courses.First().CourseID;
            var selectedCourses = new[] { courseId.ToString() };

            // Act
            var result = _controller.Create(instructor, selectedCourses) as RedirectToActionResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Index", result!.ActionName);
            var created = _context.Instructors.First(i => i.LastName == "Teacher");
            Assert.NotNull(created.CourseAssignments);
            Assert.Single(created.CourseAssignments);
        }

        [Fact]
        public void Create_Post_InvalidModel_ReturnsView()
        {
            // Arrange
            _controller.ModelState.AddModelError("LastName", "Required");
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Bad",
                HireDate = DateTime.Now,
                CourseAssignments = new List<CourseAssignment>()
            };

            // Act
            var result = _controller.Create(instructor, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
        }

        // --- Edit GET ---

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithInstructor()
        {
            // Arrange
            var instructor = _context.Instructors.First();
            // Ensure the instructor has CourseAssignments loaded
            if (instructor.CourseAssignments == null)
                instructor.CourseAssignments = new List<CourseAssignment>();

            // Act
            var result = _controller.Edit(instructor.ID) as ViewResult;

            // Assert
            Assert.NotNull(result);
        }

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Edit((int?)null) as StatusCodeResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal(400, result!.StatusCode);
        }

        // --- Delete GET ---

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithInstructor()
        {
            // Arrange
            var instructor = _context.Instructors.First();

            // Act
            var result = _controller.Delete(instructor.ID) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result!.Model as Instructor;
            Assert.NotNull(model);
            Assert.Equal(instructor.ID, model!.ID);
        }

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
