+
+namespace ContosoUniversity.Tests
+{
+    public class NotificationsControllerTests : IDisposable
+    {
+        private readonly SchoolContext _context;
+        private readonly NotificationsController _controller;
+
+        public NotificationsControllerTests()
+        {
+            _context = TestDbContextHelper.CreateContext();
+            _controller = new NotificationsController(_context);
+            _controller.ControllerContext = new ControllerContext
+            {
+                HttpContext = new DefaultHttpContext()
+            };
+            _controller.TempData = new TempDataDictionary(
+                _controller.ControllerContext.HttpContext,
+                new SessionStateTempDataProvider());
+
+            // Drain the static queue to avoid cross-test contamination
+            var svc = new NotificationService();
+            while (svc.ReceiveNotification() != null) { }
+            svc.Dispose();
+        }
+
+        public void Dispose()
+        {
+            _controller.Dispose();
+            _context.Dispose();
+        }
+
+        // --- Index ---
+
+        [Fact]
+        public void Index_ReturnsView()
+        {
+            // Act
+            var result = _controller.Index() as ViewResult;
+
+            // Assert
+            Assert.NotNull(result);
+        }
+
+        // --- GetNotifications ---
+
+        [Fact]
+        public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
+        {
+            // Act
+            var result = _controller.GetNotifications() as JsonResult;
+
+            // Assert
+            Assert.NotNull(result);
+            Assert.NotNull(result!.Value);
+
+            // Use dynamic to inspect the anonymous type
+            var value = result.Value;
+            var successProp = value!.GetType().GetProperty("success");
+            var countProp = value.GetType().GetProperty("count");
+            Assert.NotNull(successProp);
+            Assert.True((bool)successProp!.GetValue(value)!);
+            Assert.Equal(0, (int)countProp!.GetValue(value)!);
+        }
+
+        [Fact]
+        public void GetNotifications_WithNotificationsInQueue_ReturnsNotifications()
+        {
+            // Arrange - push some notifications via the service
+            var svc = new NotificationService();
+            svc.SendNotification("Student", "1", "John", EntityOperation.CREATE);
+            svc.SendNotification("Course", "2", "Math", EntityOperation.UPDATE);
+            svc.Dispose();
+
+            // Act
+            var result = _controller.GetNotifications() as JsonResult;
+
+            // Assert
+            Assert.NotNull(result);
+            var value = result!.Value;
+            var countProp = value!.GetType().GetProperty("count");
+            var count = (int)countProp!.GetValue(value)!;
+            Assert.True(count >= 1);
+        }
+
+        // --- MarkAsRead ---
+
+        [Fact]
+        public void MarkAsRead_ReturnsSuccess()
+        {
+            // Act
+            var result = _controller.MarkAsRead(1) as JsonResult;
+
+            // Assert
+            Assert.NotNull(result);
+            var value = result!.Value;
+            var successProp = value!.GetType().GetProperty("success");
+            Assert.True((bool)successProp!.GetValue(value)!);
+        }
+
+        [Fact]
+        public void MarkAsRead_NonExistentId_StillReturnsSuccess()
+        {
